def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def sections(size, separators):
        result = []
        start = 0
        for pos in separators + [size]:
            result.append((start, pos))
            start = pos + 1
        return result

    row_ranges = sections(h, sep_rows)
    col_ranges = sections(w, sep_cols)
    div_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    background = grid[0][0]

    out = []
    for r0, r1 in row_ranges:
        row = []
        for c0, c1 in col_ranges:
            marks = sum(
                grid[r][c] != background and grid[r][c] not in div_colors
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if marks == 2 else background)
        out.append(row)
    return out
